CREATE TABLE IF NOT EXISTS usuario(id BIGINT PRIMARY KEY AUTO_INCREMENT,documento VARCHAR(30) UNIQUE,nombre VARCHAR(120),correo VARCHAR(150) UNIQUE,contrasena VARCHAR(255),rol VARCHAR(20),activo BOOLEAN DEFAULT TRUE);CREATE TABLE IF NOT EXISTS idea(id BIGINT PRIMARY KEY AUTO_INCREMENT,titulo VARCHAR(180),descripcion TEXT,nivel INT,estado VARCHAR(30),observaciones TEXT,creador_id BIGINT,fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS idea_estudiante(idea_id BIGINT,estudiante_id BIGINT,PRIMARY KEY(idea_id,estudiante_id));CREATE TABLE IF NOT EXISTS proyecto(id BIGINT PRIMARY KEY AUTO_INCREMENT,codigo VARCHAR(30) UNIQUE,idea_id BIGINT,modalidad VARCHAR(80),estado VARCHAR(40));CREATE TABLE IF NOT EXISTS documento(id BIGINT PRIMARY KEY AUTO_INCREMENT,proyecto_id BIGINT,tipo VARCHAR(40),url VARCHAR(500),estado VARCHAR(30) DEFAULT 'PENDIENTE');CREATE TABLE IF NOT EXISTS pqrs(id BIGINT PRIMARY KEY AUTO_INCREMENT,usuario_id BIGINT,asunto VARCHAR(180),descripcion TEXT,estado VARCHAR(30) DEFAULT 'ABIERTA');CREATE TABLE IF NOT EXISTS notificacion(id BIGINT PRIMARY KEY AUTO_INCREMENT,mensaje VARCHAR(500),leida BOOLEAN DEFAULT FALSE);INSERT IGNORE INTO idea(id,titulo,descripcion,nivel,estado)VALUES(1,'Sistema de gestión de trabajos de grado','Plataforma web UTS.',1,'DISPONIBLE');